import React from 'react';

export default function Footer() {
  return (
    <footer className="px-4 sm:px-6 py-8 border-t border-zinc-200 dark:border-zinc-800">
      <div className="max-w-6xl mx-auto flex flex-col sm:flex-row items-center justify-between gap-2 text-sm text-zinc-500 dark:text-zinc-500">
        <p className="font-mono">© {new Date().getFullYear()} Chetanya Makkar</p>
        <p className="font-mono">built with React + Tailwind, shipped with curiosity</p>
      </div>
    </footer>
  );
}
